import hashlib,json,os,shutil,statistics,subprocess,time
from pathlib import Path
root=Path('build/review-j19-performance').resolve();root.mkdir(exist_ok=True)
output=Path('docs/review-performance/J19.json')
data={'parent_commit':'142e203','protocol':'Three alternating pairs; confirm with five extra pairs if median wall time >=20% or peak RSS >=25%. Fixed seed7, 1 thread/cell. Serial pinned CPU0; parallel pinned CPU0-3. All values and checkpoints must match. C wait4 launcher measures actual child peak RSS. No concurrent own tests/builds during runs. Profiling uses clocks around cell training/evaluation and the caller save callback; profile time is attribution, not the speed comparison. Summed cell times and ready waits overlap across cells and must not be added to wall time. Tiny batch is 100 independent 45-cell tables; sum child wall times and take maximum child RSS per batch. Hashing/cleanup are outside child time.','runs':[],'summary':[],'profiles':{},'blocked':None}
def digest(path):
 with open(path,'rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def table_digest(path):
 return {p.name:digest(p) for p in path.iterdir() if p.name=='values.txt' or p.name.endswith('.cfr.zst')}
def save():
 data['script']=Path(__file__).read_text();data['profile_prepare_script']=Path('/tmp/mus-j19-prepare-profile.py').read_text()
 data['profile_sources']={p.name:p.read_text() for p in Path('build/review-j19-profile').glob('*.c')}
 data['launcher_source']=Path('/tmp/mus-review-j12-measure.c').read_text()
 output.write_text(json.dumps(data,indent=2)+'\n')
def execute(command):
 rss=root/'rss.txt';full=['/tmp/mus-review-j12-measure',str(rss),*map(str,command)]
 start=time.perf_counter();p=subprocess.run(full,text=True,capture_output=True);elapsed=time.perf_counter()-start
 assert p.returncode==0,(command,p.returncode,p.stderr)
 return p.stdout,p.stderr,elapsed,int(rss.read_text())
def profile(stderr,rss):
 cells={}
 for line in stderr.splitlines():
  if line.startswith('J19 '):
   _,event,a,b,t=line.split();cells.setdefault((int(a),int(b)),{})[event]=float(t)
 assert len(cells)==120 and all(len(c)==4 for c in cells.values())
 start=min(c['cell-start'] for c in cells.values());end=max(c['save-end'] for c in cells.values())
 waits=[c['save-start']-c['cell-end'] for c in cells.values()]
 return {'cells':[{'score':list(k),**v} for k,v in sorted(cells.items())], 'span_seconds':end-start,'summed_cell_seconds':sum(c['cell-end']-c['cell-start'] for c in cells.values()),'save_seconds':sum(c['save-end']-c['save-start'] for c in cells.values()),'ready_wait_sum_seconds':sum(waits),'ready_wait_median_seconds':statistics.median(waits),'ready_wait_max_seconds':max(waits),'peak_rss_kib':rss}
os.sched_setaffinity(0,{0,1,2,3})
data['profiles']['parent']=profile(Path('/tmp/mus-j19-parent-profile.stderr').read_text(),int(Path('build/review-j19-profile/parent-rss.txt').read_text()))
command=[Path('build/review-j19-profile/candidate').resolve(),'--format','ordago-score','--score','32:32','--iterations','1000','--evaluation-samples','10000','--seed','7','--threads','4','--continuation',root/'profile-candidate']
stdout,stderr,wall,rss=execute(command);data['profiles']['candidate']=profile(stderr,rss)
a=table_digest(Path('build/review-j19-profile/parent-table'));b=table_digest(root/'profile-candidate');assert a==b
data['profile_artifacts_sha256']=a;data['profiles']['candidate']['command']=list(map(str,command));save()
for group,position,iterations,samples,threads,batch in [('serial-score','35:35',1000,10000,1,1),('parallel-score','32:32',1000,10000,4,1),('tiny-parallel-batch','35:35',1,1,4,100)]:
 os.sched_setaffinity(0,{0} if threads==1 else {0,1,2,3})
 reference=None
 def pair(repeat):
  global reference
  for version in (('parent','candidate') if repeat%2 else ('candidate','parent')):
   binary=Path('build/review-j18/release/mus-solver' if version=='parent' else 'build/review-j19/release/mus-solver').resolve()
   row={'group':group,'version':version,'repeat':repeat,'batch':batch,'wall_seconds':0,'peak_rss_kib':0,'children':[]}
   for index in range(batch):
    destination=root/f'{group}-{version}-{repeat}-{index}'
    command=[binary,'--format','ordago-score','--score',position,'--iterations',str(iterations),'--evaluation-samples',str(samples),'--seed','7','--threads',str(threads),'--continuation',destination]
    stdout,stderr,wall,rss=execute(command);h=table_digest(destination)
    if reference is None:reference=h
    assert h==reference,(group,version,repeat,index)
    shutil.rmtree(destination)
    row['wall_seconds']+=wall;row['peak_rss_kib']=max(row['peak_rss_kib'],rss)
    row['children'].append({'index':index,'wall_seconds':wall,'peak_rss_kib':rss})
    if index==0:row['first_command']=list(map(str,command));row['first_stdout_sha256']=hashlib.sha256(stdout.encode()).hexdigest();row['summary_line']=stdout.splitlines()[-1]
   row['identical_artifacts_sha256']=reference;data['runs'].append(row);save();print(group,version,repeat,round(row['wall_seconds'],4),row['peak_rss_kib'],flush=True)
 def summary(confirm=False):
  rows=[r for r in data['runs'] if r['group']==group and (r['repeat']>3)==confirm];s={'group':group,'confirmation':confirm}
  for field in ('wall_seconds','peak_rss_kib'):
   a=statistics.median(r[field] for r in rows if r['version']=='parent');b=statistics.median(r[field] for r in rows if r['version']=='candidate');s[field]={'parent':a,'candidate':b,'change_percent':100*(b/a-1)}
  s['trigger']=s['wall_seconds']['change_percent']>=20 or s['peak_rss_kib']['change_percent']>=25
  data['summary'].append(s);save();print(s,flush=True);return s['trigger']
 for repeat in range(1,4):pair(repeat)
 if summary():
  for repeat in range(4,9):pair(repeat)
  if summary(True):data['blocked']=group;save();break
save()

