}

static size_t automatic_information_set_reservation(
    const CliOptions *options) {
    if ((options->format != CLI_FORMAT_ORDAGO &&
         options->format != CLI_FORMAT_ORDAGO_PUBLIC) ||
        !options->iterations_set || options->load_path != NULL) {
